def transform(grid):
    h,w=len(grid),len(grid[0])
    counts={}
    for row in grid:
        for v in row: counts[v]=counts.get(v,0)+1
    # The marker is the unique color other than 0 and the dominant background/noise color(s); use the nonzero color with lowest count.
    special=[v for v in counts if v not in (0,)]
    key=min(special,key=lambda v:counts[v])
    pts=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==key]
    r0=min(r for r,c in pts);c0=min(c for r,c in pts)
    shape={(r-r0,c-c0) for r,c in pts}
    sh=max(r for r,c in shape)+1;sw=max(c for r,c in shape)+1
    out=[row[:] for row in grid]
    for r in range(h-sh+1):
      for c in range(w-sw+1):
        cells=[(r+dr,c+dc) for dr,dc in shape]
        if all(grid[rr][cc]==0 for rr,cc in cells):
          for rr,cc in cells: out[rr][cc]=key
    return out
